  String t(String key, {Map<String, Object?> params = const {}}) {
    final lang =
        _values.containsKey(locale.languageCode) ? locale.languageCode : 'ar';
    var value = TranslationCatalog.value(lang, key) ??
        _values[lang]?[key] ??
        _values['ar']?[key] ??
        key;
    for (final entry in params.entries) {
      value = value.replaceAll('{${entry.key}}', entry.value?.toString() ?? '');
    }
    return value;
  }

  TextDirection get textDirection =>
      locale.languageCode.toLowerCase().startsWith('ar')
          ? TextDirection.rtl
          : TextDirection.ltr;
}

extension AppLocalizationsX on BuildContext {
  AppLocalizations get l10n => AppLocalizations.of(this);
  String tr(String key, {Map<String, Object?> params = const {}}) =>
      AppLocalizations.of(this).t(key, params: params);
}

class _AppLocalizationsDelegate
    extends LocalizationsDelegate<AppLocalizations> {
  const _AppLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) => AppLocalizations.supportedLocales
      .any((supported) => supported.languageCode == locale.languageCode);

  @override
  Future<AppLocalizations> load(Locale locale) =>
      SynchronousFuture<AppLocalizations>(AppLocalizations(locale));

  @override
  bool shouldReload(_AppLocalizationsDelegate old) => true;
}
